from html import escape as esc
from .common import now
from . import __version__

ACTION={
 'review_negative':('优先复核','否定候选：核查相关性和现有否定，再决定否词范围；ASIN 目标单独处理。'),
 'review_reduce_bid':('复核降价','检查实际竞价、变更记录与利润，再制定金额；不由历史 CPC 猜最优竞价。'),
 'review_expansion':('复核扩量','检查是否已有精准投放、预算受限证据、当前预算、可售库存和利润；再决定预算金额。'),
 'maintain_review':('保持观察','表现接近所设目标，结合目标与库存继续复查。'),
 'observe':('继续观察','先补样本、等待归因成熟或补齐阈值，不因缺数据执行暂停或否词。')
}

def html_report(result,batch,synthetic=False):
    def e(x):return esc(str(x),quote=True)
    def ratio(x):return 'N/A' if x is None else f'{float(x)*100:.2f}%'
    def money(x):return 'N/A' if x is None else f'{float(x):,.2f}'
    scope=result['scope'];campaign=result['totals']['campaign'];search=result['totals']['search_term']
    timezone_label=scope['timezone']+('（仅计算参考；业务时区待核实）' if scope.get('timezone_confirmed',True) is False else '')
    status='合成样例 · 非真实店铺数据' if synthetic else '真实输入 · 业务建议待人工复核'
    inputs=''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in [i['type']+' / '+str(i.get('sheet') or 'CSV'),i['generated_at'],i['sha256'],str(i['row_count'])+' / '+str(i.get('raw_row_count',i['row_count']))])+'</tr>' for i in result['inputs'])
    warnings=''.join('<li>'+e(w)+'</li>' for w in result['warnings'])
    quality_html=''
    if result.get('data_quality'):
        labels={'clicks_exceed_impressions':'点击数大于曝光数','spend_without_clicks':'零点击但有花费','sales_without_orders':'零订单但有归因销售额'}
        quality_rows=[]
        for issue in result['data_quality']:
            observed=issue['observed']
            values=[issue['report_type'],issue['source_row'],observed['impressions'],observed['clicks'],observed['spend'],observed['orders'],observed['sales'],'；'.join(labels.get(k,k) for k in issue['issues'])]
            quality_rows.append('<tr>'+''.join('<td>'+e(v)+'</td>' for v in values)+'</tr>')
        quality_html='<section id="data-quality"><h2>需要核对的源数据问题</h2><p class="notice">保留原始行和金额；受影响对象只观察，不生成调整候选。此处的矛盾尚未由平台解释，不能把它推断成无效点击或退款。</p><div class="table"><table><thead><tr>'+''.join('<th>'+t+'</th>' for t in ['逻辑报表','来源行','曝光','点击','花费','订单','归因销售','问题'])+'</tr></thead><tbody>'+''.join(quality_rows)+'</tbody></table></div></section>'
    rows=[]
    for item in sorted(result['search_terms'],key=lambda x:float(x['all']['spend']),reverse=True):
        identity=item['identity'];m=item['mature'];allm=item['all'];a=item.get('action','observe');label,advice=ACTION[a]
        rows.append('<tr>'+''.join('<td>'+e(v)+'</td>' for v in [label,identity.get('campaign_id',''),identity.get('ad_group_id',''),identity.get('search_term',''),money(allm['spend']),allm['clicks'],allm['orders'],money(allm['sales']),ratio(allm['acos']),money(m['spend']),m['orders'],ratio(m['acos']),item.get('reason',''),advice,'待核实：当前设置、利润、库存；本报告不提供未经证实的金额',','.join(map(str,item.get('source_rows',[])))])+'</tr>')
    ct=[]
    for g in result['campaigns']:
        m=g['mature'];allm=g['all'];ct.append('<tr>'+''.join('<td>'+e(v)+'</td>' for v in [g['identity'].get('campaign_id',''),g['identity'].get('campaign_name',''),money(allm['spend']),money(allm['sales']),allm['orders'],ratio(allm['acos']),money(m['spend']),m['orders']])+'</tr>')
    def totalrow(label,t):
        return '<tr>'+''.join('<td>'+e(v)+'</td>' for v in [label,money(t['all']['spend']),money(t['all']['sales']),t['all']['orders'],ratio(t['all']['acos']),money(t['mature']['spend']),str(t['mature_rows'])+'/'+str(t['rows'])])+'</tr>'
    css=''' :root{--bg-page:#F7F4EC;--bg-card:#FFF;--border-card:#E3DECF;--accent:#F5C518;--accent-text:#3A3000;--dark:#2C2C2A;--text-secondary:#62685E;--accent-ink:#7A5C00;--border-control:#8A8B7B}*{box-sizing:border-box}body{margin:0;background:var(--bg-page);color:var(--dark);font:14px/1.6 system-ui,-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;font-variant-numeric:tabular-nums}main{max-width:1440px;margin:auto;padding:24px}header,section{padding:24px;background:white;border:1px solid var(--border-card);border-radius:16px;margin-bottom:16px;box-shadow:0 1px 2px #2c2c2a0a}h1{font-size:28px;font-weight:600;margin:12px 0}h2{font-size:20px;font-weight:600;margin:0 0 16px}h3{font-size:16px;font-weight:600}p{margin:8px 0}a{color:var(--accent-ink)}nav{display:flex;gap:16px;flex-wrap:wrap;padding-top:16px}.badge{display:inline-block;background:#FDF3CE;color:var(--accent-ink);padding:4px 12px;border-radius:999px}.meta{color:var(--text-secondary);overflow-wrap:anywhere}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0 8px}.metric{padding:16px;background:var(--bg-page);border:1px solid var(--border-card);border-radius:12px}.metric b{display:block;font-size:32px;font-weight:600}.table{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:12px;border-bottom:1px solid var(--border-card);vertical-align:top;overflow-wrap:anywhere}th{background:var(--bg-page);font-weight:600}.candidate-table{min-width:1600px}.notice{padding:16px;background:#FDF3CE;border-radius:8px;border-left:3px solid var(--accent-ink)}code{overflow-wrap:anywhere}.print{height:40px;background:var(--accent);border:1px solid var(--accent-ink);color:var(--accent-text);border-radius:12px;padding:8px 16px;box-shadow:inset 0 1px 0 #ffffff73,0 2px 3px #2c2c2a1f;cursor:pointer;font:inherit}.print:active{box-shadow:inset 0 1px 3px #2c2c2a29}:focus-visible{outline:2px solid var(--accent-ink);outline-offset:2px}footer{color:var(--text-secondary);font-size:12px;padding:16px 0}@media(max-width:767px){main{padding:16px}header,section{padding:16px}.metrics{grid-template-columns:1fr}h1{font-size:28px}.print{min-height:44px}.table table{min-width:640px}.table .candidate-table{min-width:1600px}}@media print{@page{size:A4 landscape;margin:12mm}body{background:white}.print,nav{display:none}main{padding:0;max-width:none}header,section{box-shadow:none;break-inside:avoid}.table{overflow:visible}table,.table table,.table .candidate-table{min-width:0;font-size:8pt}td,th{padding:6px}.candidate-table td{max-width:130px}section#candidates{break-before:page;break-inside:auto}.metrics{grid-template-columns:repeat(3,1fr)}.metric b{font-size:24pt}tr{break-inside:avoid}}'''
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>亚马逊八项全能精英 · 广告诊断</title><style>{css}</style></head><body><main>
<header><span class="badge">{e(status)}</span><h1>广告诊断与复核清单</h1><p>亚马逊八项全能精英 v1.0 · 本地工具候选版 {e(__version__)}</p><p class="meta">范围：{e(scope['account_alias'])} / {e(scope['marketplace'])} / {e(scope['currency'])} / {e(timezone_label)}</p><p class="meta">统计期：{e(scope['period']['start'])} 至 {e(scope['period']['end'])}；归因窗口：{e(scope['attribution_window_days'])} 天；缓冲假设：{e(scope['reporting_lag_hours'])} 小时</p><p class="meta">归因判断时点：{e(result['maturity_as_of'])}；报告生成：{e(now())}</p><p class="meta">批次：<code>{e(batch)}</code></p><nav><a href="#summary">总体情况</a><a href="#campaigns">活动</a><a href="#candidates">搜索词候选</a><a href="#evidence">数据与限制</a><button class="print" onclick="window.print()">打印 / 保存 PDF</button></nav></header>{quality_html}
<section id="summary"><h2>先看这三个指标</h2><div class="metrics"><div class="metric">活动全期花费（{e(scope['currency'])}）<b>{money(campaign['all']['spend'])}</b></div><div class="metric">活动全期归因销售额（{e(scope['currency'])}）<b>{money(campaign['all']['sales'])}</b></div><div class="metric">活动全期 ACOS<b>{ratio(campaign['all']['acos'])}</b></div></div><div class="notice">指标反映归因效率，不是净利润。活动与搜索词报表不相加。本次不修改竞价、预算、否定或任何店铺设置。</div><div class="table"><table><thead><tr><th>来源</th><th>全期花费</th><th>全期归因销售</th><th>订单</th><th>全期 ACOS</th><th>成熟花费</th><th>成熟行/全部行</th></tr></thead><tbody>{totalrow('活动',campaign)}{totalrow('搜索词',search)}</tbody></table></div></section>
<section id="campaigns"><h2>活动层级表现（全期与成熟数据分列）</h2><div class="table"><table><thead><tr><th>活动 ID</th><th>活动名称</th><th>全期花费</th><th>全期归因销售</th><th>全期订单</th><th>全期ACOS</th><th>成熟花费</th><th>成熟订单</th></tr></thead><tbody>{''.join(ct)}</tbody></table></div></section>
<section id="candidates"><h2>具体对象与解决方案</h2><p>按全期花费降序展示；全期事实与成熟指标分列，成熟花费为0不代表实际没花费。候选判断只使用成熟数据。这里的否定、降价与扩量均待复核，不是可上传的后台批量操作表。</p><div class="table"><table class="candidate-table"><thead><tr>{''.join('<th>'+x+'</th>' for x in ['建议类别','活动 ID','广告组 ID','搜索词/目标','全期花费','全期点击','全期订单','全期归因销售','全期ACOS','成熟花费','成熟订单','成熟ACOS','判断依据','解决方案','金额与执行前提','原始来源行'])}</tr></thead><tbody>{''.join(rows)}</tbody></table></div><h3>复查方式</h3><p>先核对当前投放与商品相关性、利润和可售库存；获得具体操作授权后再执行。按已确认的归因窗口与报表缓冲重新取数，对比同范围指标，记录期间的价格、促销和缺货变化。</p></section>
<section id="evidence"><h2>数据来源、日期与未完成项</h2><div class="table"><table><thead><tr><th>报表</th><th>生成时刻</th><th>输入 SHA-256</th><th>分析行 / 原始行</th></tr></thead><tbody>{inputs}</tbody></table></div><h3>实际使用的规则</h3><p class="meta">{e(result['rules'])}</p><ul>{warnings}</ul><p>完整字段映射、来源行、日期覆盖与成熟度见 metrics.json；数据库保留本批原始文件、原始行、分析结果与此 HTML。后续可从数据库重新导出报告。</p><div class="notice">成本、实际发货费用、当前竞价/预算与变更记录不包含在两份基础报表中，因此不编造“具体加多少美元”或“实际净利润”。</div></section><footer>AEPI 家族 UI v1.4 · 本地样式适配。第三方平台账号与模型费用不包含在免费开源工具中。</footer></main></body></html>'''
